// Do-and-announce shell-integration + config bootstrap (str87-fgos-setup-doctor
// D6, retargeted per tsk-2ta D1 amended / tsk-5vf D2/D4): inserts the
// shell-integration source line into every DETECTED rc file (bash/zsh,
// D4) — never creates a new rc file (shell-rc.mjs's own refusal) — then
// ensures the shared config file (`.fgos/config.json`) exists and has
// every current default key from EVERY registered `registerConfigDefault`
// entry, via `ensureSharedConfigDefaults` (the one write path allowed
// here; `doctor`, unlike `setup`, never calls it). tsk-1ri: also ensures
// the GLOBAL config file (`~/.fgos/config.json`) the same way —
// `ensureSharedConfigDefaults` is already generic over its `dir`
// argument (`sharedConfigFilePath(os.homedir())` resolves to the exact
// same path `src/config/global-config.mjs`'s `defaultGlobalConfigPath()`
// uses), so this reuses it as-is rather than adding a parallel
// global-specific writer.
case 'setup': {
  // tsk-2xj: same --dir resolution as `doctor`/`uninstall` below and
  // `resync-worktree` (:4939) — setup's writes are unconditional (tsk-5hi),
  // so run from a linked worktree this used to materialize .fgos/config.json
  // INSIDE the worktree (ADR0020 violation), not just report wrong.
  const repoRoot = flags.dir !== undefined ? path.dirname(dir) : (resolveMainCheckoutRoot(process.cwd()) ?? process.cwd());
  const scriptPath = integrationScriptPath();
  const rcFiles = detectRcFiles(os.homedir());
  const rcFilesInserted = [];
  const rcFilesAlreadyConfigured = [];
  // A null scriptPath means this copy of fgos has no location stable enough
  // to name in a shell profile — it is not inside a git checkout, so it is
  // ephemeral by nature. Writing its path would leave a `source` line that
  // outlives the directory it points at and errors on every shell open.
  // Everything else setup does still runs; only the rc write is declined.
  const rcWriteDeclinedReason = scriptPath === null
    ? 'this copy of fgos is not inside a git checkout, so it has no stable path to source — source scripts/fgos-shell-integration.sh by hand from a permanent checkout'
    : null;
  if (scriptPath !== null) {
    for (const rcFile of rcFiles) {
      if (insertSourceLine(rcFile, scriptPath)) {
        rcFilesInserted.push(rcFile);
      } else {
        rcFilesAlreadyConfigured.push(rcFile);
      }
    }
  }
  const configPath = sharedConfigFilePath(repoRoot);
  const configExisted = fs.existsSync(configPath);
  const { addedKeys } = ensureSharedConfigDefaults(repoRoot);
  const globalConfigPath = sharedConfigFilePath(os.homedir());
  const globalConfigExisted = fs.existsSync(globalConfigPath);
  const { addedKeys: globalAddedKeys } = ensureSharedConfigDefaults(os.homedir());
  // str65-6/str88: wires core.hooksPath the same way `npm run setup:hooks`
  // does — a second, non-npm-lifecycle-dependent activation path for the
  // main-checkout lock hook, since pnpm 10+ blocks `prepare` for a
  // git-hosted dependency (str88) and nothing re-automated it since.
  // Idempotent, no-ops silently when repoRoot has no `.git` at all.
  // Fill-only like the two side effects above: a pre-existing custom
  // core.hooksPath is left untouched, never silently repointed.
  const { wired: hooksWired, skippedExisting: hooksSkippedExisting } = installGitHooks(repoRoot);
  // tsk-60f D1/D5: wires the PreToolUse dispatch-decide enforcement hook
  // into .claude/settings.json the same fill-only way — a pre-existing
  // hooks.SessionStart entry (or any other settings.json content) is
  // left untouched; a malformed settings.json is left alone entirely.
  const { wired: dispatchDecideHookWired, skippedExisting: dispatchDecideHookSkippedExisting } = installClaudeCodeHook(repoRoot);
  // tsk-5hi: setup now also runs every registered fix — the same
  // runFixes() `doctor --fix` already calls (RUL9/RUL11) — instead of
  // leaving a person to separately discover and run `doctor --fix` to
  // reach the state a plain `setup` should already leave a project in.
  // Unconditional, no confirmation, per RUL10's existing act-then-report
  // contract for this verb; every registered fix is already required
  // idempotent/fail-soft, so running the full list here is safe.
  const fixed = runFixes(repoRoot);
  // tsk-1qi D5/D7: materializes `.agents/skills` (canonical source) +
  // generated `.claude/skills` thin wrappers into repoRoot -- copying
  // from THIS running copy's own package root when repoRoot is a
  // different (external) project, or just regenerating wrappers
  // in-place for forgentX's own dev-checkout self-hosting run (see
  // materializeSkillsIntoProject's own self-hosting no-copy branch).
  const { copied: skillsSourceCopied, wrappersWritten: skillWrappersGenerated } = materializeSkillsIntoProject(PACKAGE_ROOT, repoRoot);
  const deprecation = COMMAND_REGISTRY.find((entry) => entry.name === 'setup')?.deprecated ?? null;
  const deprecationText = formatDeprecation(deprecation);
  return {
    deprecation,
    deprecationMessage: deprecationText
      ? `fgos setup is legacy compatibility; ${deprecationText}.`
      : undefined,
    rcFilesInserted,
    rcFilesAlreadyConfigured,
    ...(rcWriteDeclinedReason !== null && { rcWriteDeclinedReason }),
    configPath,
    configCreated: !configExisted,
    configAddedKeys: configExisted ? addedKeys : [],
    globalConfigPath,
    globalConfigCreated: !globalConfigExisted,
    globalConfigAddedKeys: globalConfigExisted ? globalAddedKeys : [],
    hooksWired,
    hooksSkippedExisting,
    dispatchDecideHookWired,
    dispatchDecideHookSkippedExisting,
    fixed,
    skillsSourceCopied,
    skillWrappersGenerated: skillWrappersGenerated.length,
  };
}

// Reverses `setup`'s own wiring (tsk-4iv-1, docs/history/fgos-uninstall/
// CONTEXT.md D2-D4). Requires `--yes` (D3): with no flag, refuses before
// touching anything — destructive, unlike `setup`/`doctor`, which never
// ask. Two side effects, both mirroring `setup`'s own fill-only rules in
// the opposite direction:
//   - git hooks (D2): `uninstallGitHooks` unwires `core.hooksPath` and
//     deletes `.githooks/pre-commit` (+ the dir, if left empty) ONLY when
//     hooksPath is still exactly `.githooks` — a custom value the caller
//     repointed is left untouched, same as `installGitHooks` leaves one
//     alone when installing.
//   - shell-rc (D4): never edits an rc file — reuses `hasSourceLine`
//     read-only, the same primitive `deadSourceLines`/`doctor` already
//     use, to report which rc file(s) still carry the fgOS source line so
//     the caller can remove it by hand (docs/history/
//     shell-rc-dead-source-lines/CONTEXT.md D1: "deletion stays a human
//     act" — this item does not carve out an exception to that).
// Never touches `.fgos/` data or `.fgos/config.json` (pinned constraint,
// CONTEXT.md) — structurally true: this case never imports or calls any
// config-writing function (`ensureSharedConfigDefaults`/`writeSharedConfig`).
//
// Package removal (D1, tsk-4iv-2 SPIKE): opt-in via `--remove-package`,
// additive on top of tsk-4iv-1's already-shipped, already-documented
// default behavior (`--yes` alone stays wiring-only, byte-identical to
// before this flag existed — preserves that contract rather than
// silently widening it). Scoped narrowly per the spike's own locked
// scope: npm global installs only, Linux/macOS only — shells out to
// `npm uninstall -g forgent`, the officially-supported removal path,
// rather than hand-rolling file deletion. Runs LAST, after the
// confirmation gate and wiring reversal above, since removing the
// package first would strand the process mid-run before it could
// finish undoing its own wiring (plan.md's own ordering rationale).
// Never throws on failure — a failed removal is exactly the outcome
// this spike exists to measure, not a bug to crash on.
case 'uninstall': {
  if (!flags.yes) {
    throw new StoreError(
      'validation',
      'fgos uninstall requires --yes to confirm — it unwires git hooks (core.hooksPath/.githooks) and reports (never deletes) the shell-rc source line. Rerun with --yes once ready.',
    );
  }
  // tsk-2xj: same --dir resolution as `doctor`/`setup` above.
  const repoRoot = flags.dir !== undefined ? path.dirname(dir) : (resolveMainCheckoutRoot(process.cwd()) ?? process.cwd());
  const scriptPath = integrationScriptPath();
  const shellRcSourceLinesFound = scriptPath === null
    ? []
    : detectRcFiles(os.homedir())
      .filter((rcFile) => hasSourceLine(rcFile, scriptPath))
      .map((rcFile) => ({ rcFile, sourceLine: `source "${scriptPath}"` }));
  const { unwired: hooksUnwired, skippedExisting: hooksSkippedExisting } = uninstallGitHooks(repoRoot);
  let packageRemoval = { attempted: false, outcome: null };
  if (flags['remove-package']) {
    // tsk-652: `npm uninstall -g forgent` exits 0 and reports nothing
    // wrong even when this copy was never npm-installed at all (a
    // pnpm/yarn global install lives in a different store npm never
    // touches) -- confirm npm's own global node_modules actually has
    // this package BEFORE claiming success, the same "detected
    // manager" scope tsk-4iv-2's own SPIKE locked (npm-only), never
    // widened here to actually support pnpm/yarn removal.
    let npmRootG = null;
    const npmCmd = process.platform === 'win32' ? 'npm.cmd' : 'npm';
    try {
      npmRootG = execFileSync(npmCmd, ['root', '-g'], { encoding: 'utf8', shell: process.platform === 'win32' }).trim();
    } catch {
      npmRootG = null;
    }
    const npmInstalled = npmRootG !== null && npmRootG !== '' && fs.existsSync(path.join(npmRootG, 'forgent'));
    if (!npmInstalled) {
      packageRemoval = {
        attempted: false,
        outcome: 'skipped',
        reason: npmRootG
          ? `this copy of fgOS is not visible under npm's own global node_modules (${npmRootG}) -- --remove-package only supports npm global installs (tsk-4iv-2); if installed via pnpm/yarn, remove it with that tool's own global uninstall command instead`
          : 'npm root -g did not resolve (npm not on PATH?) -- --remove-package only supports npm global installs (tsk-4iv-2), and could not confirm this is one',
      };
    } else {
      try {
        const output = execFileSync(npmCmd, ['uninstall', '-g', 'forgent'], { encoding: 'utf8', shell: process.platform === 'win32' });
        packageRemoval = { attempted: true, outcome: 'removed', output };
      } catch (err) {
        packageRemoval = {
          attempted: true,
          outcome: 'failed',
          error: err.message,
          stderr: typeof err.stderr === 'string' ? err.stderr : (err.stderr?.toString() ?? null),
        };
      }
    }
  }
  return {
    shellRcSourceLinesFound,
    packageRemoval,
    shellRcRemovalInstructions: shellRcSourceLinesFound.length > 0
      ? 'fgOS never edits your shell profile — remove the line(s) above by hand.'
      : null,
    hooksUnwired,
    hooksSkippedExisting,
  };
}

// Diagnostic by default (D2, docs/specs/distribution.md RUL9): runs every
// DOCTOR_CHECKS entry against the current cwd, writing nothing — no rc
// file insertion, no config write — unless `--fix` is given.
//
// `--fix` (docs/history/doctor-fix-gate-bypass/CONTEXT.md D2, deliberate
// reversal of RUL9/RUL11 per distribution-vision.md §3): runs every
// registered `fix` (`runFixes`, `src/setup/registrations.mjs`) BEFORE
// re-running the checks, so the returned `checks` array reflects
// post-fix state — the same "report what changed" shape
// `ensureRunnerConfig`/`ensureSharedConfigDefaults` already use. Without
// `--fix`, behavior is byte-identical to before this flag existed.
case 'doctor': {
  // tsk-2xj: resolve the real main checkout the same way `resync-worktree`
  // (:4939) already does — an explicit --dir always wins, otherwise
  // self-detect via resolveMainCheckoutRoot so this reports/fixes the
  // shared store even when run from a linked worktree (ADR0020: a
  // worktree never carries its own .fgos/, so process.cwd() there was
  // silently checking/writing the wrong tree).
  const repoRoot = flags.dir !== undefined ? path.dirname(dir) : (resolveMainCheckoutRoot(process.cwd()) ?? process.cwd());
  const fixed = flags.fix ? runFixes(repoRoot) : undefined;
  // A check may return its result directly or as a promise (one drives promise-based runner code).
  const checks = [];
  for (const { id, description, check } of DOCTOR_CHECKS) {
    const { passed, message } = await check(repoRoot);
    checks.push({ id, description, passed, message });
  }
  return fixed === undefined ? { checks } : { fixed, checks };
}

case 'unclaim': {
  const id = requireField(positional[0] ?? flags.id, 'unclaim requires an id: fgos unclaim <id>');
  const repoRoot = flags.dir !== undefined ? path.dirname(dir) : (resolveMainCheckoutRoot(process.cwd()) ?? process.cwd());
  const claim = readClaim(dir, id);
  if (!claim) return { released: false, reason: 'no-claim' };
  const durableView = rebuildViewFromDir(dir);
  const durableStatus = durableView.work[id]?.status;

      // Operator recovery: the claim may belong to another (often dead)
      // session, so both release paths name their reason through the admin
      // option; the owner-only default would refuse them.
      // Releasing another writer's claim leaves a durable engine decision naming
      // both writers, so the release can be audited after the claim file is gone.
      const recordAdminRelease = (rel) => {
        if (!rel.admin) return;
        const known = durableView.work[id] !== undefined;
        addDecision(dir, {
          ...(known ? { id } : {}),
          text: `admin claim release (${rel.admin.reason}): released claim ${claim.claimId} on "${id}" owned by writer ${rel.admin.ownerWriterId}, as writer ${rel.admin.releasedByWriterId}`,
          source: 'unclaim',
          kind: 'engine',
          rationale: 'operator recovery of an orphaned or stale runtime claim through fgos unclaim',
          admin: { ...rel.admin, claimId: claim.claimId, ...(known ? {} : { itemId: id }) },
        });
      };
      if (durableStatus !== 'doing') {
        const rel = releaseClaim(dir, { id, claimId: claim.claimId, adminReason: 'unclaim:durable-status-mismatch' });
        if (!rel.released) return rel;
        recordAdminRelease(rel);
        return { released: true, reason: 'durable-status-mismatch', durableStatus: durableStatus ?? 'not-found', ...(rel.admin ? { admin: rel.admin } : {}) };
      }
      if (!isReclaimEligible(repoRoot, id, claim.claimRole)) {
        const holderDesc = `writer ${claim.writerId ?? 'unknown'}` + (claim.actor ? ` (${claim.actor})` : '');
        const ageMs = claim.acquiredAt ? Date.now() - new Date(claim.acquiredAt).getTime() : NaN;
        const ageDesc = Number.isFinite(ageMs) ? formatLockDurationMs(ageMs) : 'unknown age';
        throw new ClaimError(
          'conflict',
          `unclaim: claim for "${id}" is held by ${holderDesc}, acquired ${ageDesc} ago -- refusing to clear live claim.`,
        );
      }
      const rel = releaseClaim(dir, { id, claimId: claim.claimId, adminReason: 'unclaim:stale-liveness' });
      if (!rel.released) return rel;
      recordAdminRelease(rel);
      return { released: true, reason: 'stale-liveness', ...(rel.admin ? { admin: rel.admin } : {}) };
    }

    case 'preflight': {
      const cwd = flags.dir !== undefined ? path.resolve(flags.dir) : process.cwd();
      const repoRoot = execFileSync('git', ['rev-parse', '--show-toplevel'], { cwd, encoding: 'utf8' }).trim();

      const checks = [];

      // 1. mirror-sync-diff
      {
        const id = 'mirror-sync-diff';
        const description = 'Verify skill wrappers across .claude/skills and plugins/fgOS/skills are in sync with source';
        const npmCmd = process.platform === 'win32' ? 'npm.cmd' : 'npm';
        const buildRes = spawnSync(npmCmd, ['run', 'build:skills'], {
          cwd: repoRoot,
          encoding: 'utf8',
          shell: process.platform === 'win32',
        });
        if (buildRes.status !== 0) {
          const msg = (buildRes.error?.message || buildRes.stderr || buildRes.stdout || 'npm run build:skills failed').trim();
          checks.push({ id, description, passed: false, message: msg });
        } else {
          const diffRes = spawnSync('git', ['diff', '--exit-code', '--', '.claude/skills', 'plugins/fgOS/skills'], { cwd: repoRoot, encoding: 'utf8' });
          if (diffRes.status !== 0) {
            const msg = (diffRes.stdout || diffRes.stderr || 'uncommitted skill wrapper drift in .claude/skills or plugins/fgOS/skills').trim();
            checks.push({ id, description, passed: false, message: msg });
          } else {
            checks.push({ id, description, passed: true, message: 'skill wrappers in .claude/skills and plugins/fgOS/skills are in sync' });
          }
        }
      }

      // 2. decision-citation-drift
      {
        const id = 'decision-citation-drift';
        const description = 'Verify decision citations across specs and skills do not drift from decision index';
        const res = spawnSync(process.execPath, ['scripts/check-decision-citation-drift.mjs'], { cwd: repoRoot, encoding: 'utf8' });
        if (res.status !== 0) {
          const msg = (res.stdout || res.stderr || 'decision citation drift check failed').trim();
          checks.push({ id, description, passed: false, message: msg });
        } else {
          checks.push({ id, description, passed: true, message: (res.stdout || 'no decision citation drift found').trim() });
        }
      }

      // 3. backlog-reconciliation
      {
        const id = 'backlog-reconciliation';
        const description = 'Verify backlog item status reconciliation';
        const res = spawnSync(process.execPath, ['scripts/check-backlog-reconciliation.mjs'], { cwd: repoRoot, encoding: 'utf8' });
        if (res.status !== 0) {
          const msg = (res.stderr || res.stdout || 'backlog reconciliation check failed').trim();
          checks.push({ id, description, passed: false, message: msg });
        } else {
          checks.push({ id, description, passed: true, message: (res.stdout || 'all backlog items reconciled').trim() });
        }
      }

      const failures = checks.filter((c) => !c.passed);
      if (failures.length > 0) {
        const failureList = failures.map((c) => `  - ${c.id}: ${c.message}`).join('\n');
        throw new StoreError('validation', `fgos preflight: ${failures.length} of ${checks.length} check(s) failed:\n${failureList}`);
      }

      return { checks };
    }

    // `lock fence`: stop the process that holds a registry lock so the lock
    // can be taken again. Never takes a lock from a live holder: holders are
    // listed, signalled by identity (SIGTERM, then SIGKILL), and the kernel
    // is asked with a probe whether the lock is free afterwards.
    case 'lock': {
      const sub = requireField(positional[0], 'lock requires a sub-verb: fgos lock fence <name> [--param k=v] [--yes] [--attest-stopped]');
      if (sub === 'fence') {
        const name = requireField(positional[1], 'lock fence requires a lock name: fgos lock fence <name> (names: fgos lock-status)');
        try {
          return await fenceLock({
            name,
            fgosDir: dir,
            params: parseLockParams(flags.param),
            attestStopped: Boolean(flags['attest-stopped']),
            confirm: (holders) => (flags.yes ? true : confirmFence(name, holders)),
          });
        } catch (err) {
          throw lockErrorToStoreError(err, 'lock fence');
        }
      }
      throw new StoreError('validation', `unknown lock sub-verb "${sub}". Usage: fgos lock fence <name> [--param k=v] [--yes] [--attest-stopped]`);
    }

    case 'lock-status': {
      const { mainCheckout, locks } = collectLockStatus({ fgosDir: dir });
      // The commit-activity beacon is reported on its own: it is a hint the
      // pre-commit hook reads, never a lock claim/land/approve wait on.
      const beacon = readBeacon(dir);
      return {
        mainCheckout,
        locks,
        beacon: beacon.status === 'ok'
          ? {
            status: 'present',
            writer: beacon.record.writer.id,
            ageMs: Date.now() - beacon.record.writtenAt,
            windowMs: beacon.record.windowMs,
            active: Date.now() - beacon.record.writtenAt <= beacon.record.windowMs,
          }
          : { status: beacon.status },
      };
    }

    // tsk-1d7 (docs/history/stale-worktree-index-guard/CONTEXT.md D3): the
    // repair verb `.githooks/pre-commit`'s own stale-index guard (D2)
    // prints as its refuse-message command. Run FROM INSIDE the stale
    // worktree (the same place the hook just refused a commit) — `--path`
    // exists only so a test/caller can point this at a worktree other than
    // its own cwd. `resyncWorktree`'s own `repoRoot` param must be the MAIN
    // checkout, never the worktree itself, since branch refs and
    // `--git-common-dir` must resolve against the shared repo (tsk-jgs:
    // `dir` alone is NOT that root here -- `dir` is `dataDir(flags.dir)`,
    // which for the bare/default invocation this case exists to support is
    // cwd-strict, never git-resolved, per `dataDir`'s own doc comment
    // above -- so it silently resolves to `<worktreePath>/.fgos`, a path
    // that never exists on disk for a linked worktree, ADR0020). When
    // `--dir` is given explicitly, `path.dirname(dir)` recovers the
    // caller-supplied root correctly, same as every other verb here; when
    // it is omitted, resolve the real main checkout the same way
    // `dispatch.mjs`/`registrations.mjs` already do for exactly this
    // worktree-or-main-checkout ambiguity: `resolveMainCheckoutRoot`
    // (`src/runner/paths.mjs`), which shells `git --git-common-dir` from
    // the worktree itself.
    case 'resync-worktree': {
      const worktreePath = flags.path ? path.resolve(flags.path) : process.cwd();
      const branch = flags.branch ?? gitAt(worktreePath, ['symbolic-ref', '--short', 'HEAD']).trim();
      const repoRoot = flags.dir !== undefined ? path.dirname(dir) : (resolveMainCheckoutRoot(worktreePath) ?? path.dirname(dir));
      return resyncWorktree(repoRoot, worktreePath, branch);
    }

    // tsk-3au: the safe path for a destructive `git reset --hard` on the
    // main checkout — refuses when the whole-repo tree is dirty (reusing
    // `isMainTreeClean`, the same whole-repo check `approve` already uses,
    // never a fresh git-status reimplementation) unless the caller passes
    // `--confirm` after seeing the full status this case prints into the
    // error. `repoRoot` is derived from `dir` (never `process.cwd()`) so
    // this verb behaves identically whether invoked from the main checkout
    // or, per this item's own theme, from a worktree's cwd with `--dir`.
    //
    // tsk-5iv D1 (round-3 review, HIGH): `repoRoot = path.dirname(dir)` and
    // `dir` defaults to `dataDir(undefined)` -- cwd-strict, never
    // git-resolved (paths.mjs's own `strict: true` contract). Called with
    // no `--dir` from inside a linked worktree, `repoRoot` silently
    // resolves to the WORKTREE, not the main checkout, while this verb's
    // own error text below still prints "main checkout, whole repo" and
    // (with --confirm) runs `git reset --hard` against that wrong tree --
    // the exact destructive-reset-on-the-wrong-tree failure mode AGENTS.md
    // tells every session to use THIS verb instead of raw `git reset
    // --hard` to avoid. Refuse outright rather than silently proceed,
    // matching the same `isMainWorktree` guard other verbs in this file
    // already use (e.g. the `init`/`approve --github` cases above).
    case 'main-checkout-reset': {
      const sha = requireField(flags.sha, 'main-checkout-reset requires --sha <sha>: fgos main-checkout-reset --sha <sha> [--confirm]');
      const repoRoot = path.dirname(dir);
      if (flags.dir === undefined && !isMainWorktree(repoRoot)) {
        throw new StoreError(
          'validation',
          'main-checkout-reset: refusing to run without --dir <mainRoot> -- cwd is a linked worktree, and without --dir this verb would silently ' +
            'target it (git reset --hard) instead of the main checkout. Pass --dir <mainRoot> explicitly, e.g. ' +
            '`fgos main-checkout-reset --sha <sha> --dir "$(git rev-parse --path-format=absolute --git-common-dir | xargs dirname)"`.',
        );
      }
      const reset = async () => {
        const confirmed = Boolean(flags.confirm);
        const dirty = !isMainTreeClean(repoRoot);
        let lostCommitCount = 0;
        let lostCommitsOutput = '';
        try {
          const revList = gitAt(repoRoot, ['rev-list', `${sha}..HEAD`]).trim();
          if (revList) {
            const commits = revList.split('\n').filter(Boolean);
            lostCommitCount = commits.length;
            if (lostCommitCount > 0) {
              lostCommitsOutput = gitAt(repoRoot, ['log', `${sha}..HEAD`, '--format=%h %an (%ae): %s', '--stat']).trim();
            }
          }
        } catch (_err) {
          // If git rev-list fails (e.g. invalid SHA), reset --hard below will fail with git's error.
        }

        try {
          assertSafeMainCheckoutReset({ dirty, confirmed, lostCommitCount, sha });
        } catch (err) {
          let details = `main-checkout-reset: ${err.message}`;
          if (dirty) {
            const statusOutput = gitAt(repoRoot, ['status', '--porcelain']).trim();
            details += `\n\nFull git status (main checkout, whole repo):\n${statusOutput || '(empty)'}`;
          }
          if (lostCommitCount > 0) {
            details += `\n\nCommits about to be discarded (${lostCommitCount}):\n${lostCommitsOutput || '(none)'}`;
          }
          throw new StoreError('validation', details);
        }
        gitAt(repoRoot, ['reset', '--hard', sha]);
        return { sha, wasDirty: dirty, lostCommitCount, confirmed };
      };
      try {
        return await withMainCheckout(createLockScope('main-checkout-reset'), 'reset', reset, { fgosDir: dir });
      } catch (err) {
        throw lockErrorToStoreError(err, 'main-checkout-reset');
      }
    }

    default:
      throw new StoreError('validation', `unknown verb "${verb ?? ''}". Usage: fgos <version|init|add|submit|discover|plan|move|retrospective|cleanup|compound|edit|item|ask|answer|decision|list|ready|rebuild|repair|rollup|take|return|review|approve|sync-root|reject|catchup|triage|session|gateway|goal|tool|setup|doctor|lock|lock-status|main-checkout-reset> ...`);
  }
}

// ─── --help / --help --json: machine-readable verb manifest (P37 deliverable
// b) — mirrors `.bee/bin/bee.mjs`'s publicManifestEntries/renderHelpText/
// handleHelp exactly. The manifest itself is NEVER wrapped in the fgos.v1
// envelope (wrapEnvelope) — this is CTR001's documented exception for the
// verb manifest: metadata about the CLI's own verb surface, not a verb's
// data payload, the same distinction bee.mjs draws for its own
// `--help --json`.

function publicManifestEntries() {
  return COMMAND_REGISTRY.map(({ name, invoke, description, parameters, examples, subcommands, touchesState, externalEffect, paginated, deprecated }) => ({
    name,
    invoke,
    description,
    parameters,
    examples,
    ...(subcommands ? { subcommands } : {}),
    touchesState,
    externalEffect,
    paginated,
    deprecated,
  }));
}

// A required param that can be supplied positionally (mixed) or ONLY
// positionally (e.g. submit's text, session's sub) is never a real `--flag`
// on the command line — printing it as `required: --name` would be actively
// wrong for the positional-only case (STR77) and misleading for the mixed
// case. Split required into the two shapes so each renders in its own idiom;
// only the flag-only remainder still gets the `--name` form.
function renderParameterLines(parameters, indent) {
  const lines = [];
  const required = parameters?.required || [];
  const positional = parameters?.positional || [];
  const flagRequired = required.filter((r) => !positional.includes(r));
  if (positional.length) lines.push(`${indent}positional: ${positional.join(', ')}`);
  if (flagRequired.length) lines.push(`${indent}required: ${flagRequired.map((r) => `--${r}`).join(', ')}`);
  return lines;
}

function renderHelpText(entries = publicManifestEntries()) {
  // Label for touchesState+externalEffect: 'read' (both false), 'write'
  // (touches only), 'external' (effect only), or 'write+external' (both true).
  const labelFor = (touchesState, externalEffect) => {
    if (touchesState && externalEffect) return 'write+external';
    if (touchesState) return 'write';
    if (externalEffect) return 'external';
    return 'read';
  };
  const lines = [`fgos — the fgOS work-item CLI (schema_version ${MANIFEST_SCHEMA_VERSION})`, ''];
  for (const entry of entries) {
    const label = labelFor(entry.touchesState, entry.externalEffect);
    lines.push(`${entry.invoke} [${label}]`);
    lines.push(`    ${entry.description}`);
    lines.push(...renderParameterLines(entry.parameters, '    '));
    for (const [sub, spec] of Object.entries(entry.subcommands ?? {})) {
      lines.push(`    fgos ${entry.name} ${sub}`);
      lines.push(`        ${spec.description}`);
      lines.push(...renderParameterLines(spec.parameters, '        '));
    }
    const deprecationText = formatDeprecation(entry.deprecated);
    if (deprecationText) {
      lines.push(`    DEPRECATED — ${deprecationText}`);
    }
    lines.push('');
  }
  return `${lines.join('\n').trimEnd()}\n`;
}

// Help is the manifest door: metadata about the CLI's own verb surface, never
// a verb's data payload, so it is NEVER wrapped in the fgos.v1 envelope
// (CTR001's documented exception, the same distinction bee.mjs draws for its
// own `--help --json`), and it never runs a verb (no side effects, e.g.
// `init --help` must never call initStore). A refused help request writes one
// stderr line and exits 4 (validation), with nothing on stdout.
function refuseHelp(message) {
  process.stderr.write(`fgos: ${message}\n`);
  process.exitCode = 4;
}

// One verb's help: its manifest entry, narrowed to one sub-verb when `sub` is
// given. Returns false when the request is refused (already reported).
function printVerbHelp(verb, sub, json) {
  const entry = publicManifestEntries().find((e) => e.name === verb);
  if (!entry) {
    refuseHelp(`unknown verb "${verb}". Usage: fgos --help [<verb> [<sub>]] [--json]`);
    return false;
  }
  let shown = entry;
  if (sub !== undefined) {
    if (!entry.subcommands) {
      refuseHelp(`${verb} takes no sub-verb (got "${sub}"). Usage: fgos ${verb} --help [--json]`);
      return false;
    }
    if (!Object.hasOwn(entry.subcommands, sub)) {
      refuseHelp(`unknown ${verb} sub-verb "${sub}" (known: ${Object.keys(entry.subcommands).join(', ')}).`);
      return false;
    }
    shown = { ...entry, subcommands: { [sub]: entry.subcommands[sub] } };
  }
  process.stdout.write(json ? `${JSON.stringify(shown, null, 2)}\n` : renderHelpText([shown]));
  return true;
}

// `fgos --help|-h [<verb> [<sub>]] [--json]`: the whole manifest, or one
// verb's entry. Anything else on the line is refused rather than ignored.
function handleHelp(args) {
  const json = args.includes('--json');
  // `--dir <root>` is the global store flag (the `fgos` shell function appends
  // it to every call); help reads no store, so it is accepted and unused. A
  // repeated help token (`fgos -h --help`) asks the same thing.
  const words = args
    .filter((a, i) => !(a === '--dir' || a.startsWith('--dir=') || (i > 0 && args[i - 1] === '--dir')))
    .filter((a) => a !== '--json' && a !== '--help' && a !== '-h');
  const option = words.find((a) => a.startsWith('-'));
  if (option !== undefined) {
    refuseHelp(`unknown option "${option}" for --help. Usage: fgos --help [<verb> [<sub>]] [--json]`);
    return;
  }
  if (words.length > 2) {
    refuseHelp(`too many words for --help: "${words.join(' ')}". Usage: fgos --help [<verb> [<sub>]] [--json]`);
    return;
  }
  if (words.length > 0) {
    printVerbHelp(words[0], words[1], json);
    return;
  }
  if (json) {
    const manifest = { schema_version: MANIFEST_SCHEMA_VERSION, commands: publicManifestEntries() };
    process.stdout.write(`${JSON.stringify(manifest, null, 2)}\n`);
  } else {
    process.stdout.write(renderHelpText());
  }
}

// Per-verb `fgos <verb> [<sub>] --help|-h [--json]` (STR79/D3): the same door
// one level down. For a verb with sub-verbs, the first positional names the
// sub-verb to narrow to; any other verb's positionals are its own arguments
// (e.g. run's prompt) and are ignored. An unknown verb returns null so the
// normal dispatch path still produces its usual "unknown verb" error.
function handleVerbHelp(verb, flags, positional) {
  const entry = COMMAND_REGISTRY.find((e) => e.name === verb);
  if (!entry) return null;
  // `--help <word>` hands the word to the flag as its value.
  const words = [...(typeof flags.help === 'string' ? [flags.help] : []), ...positional].filter((w) => w !== '-h');
  printVerbHelp(verb, entry.subcommands ? words[0] : undefined, flags.json !== undefined);
  return true;
}

// `--pretty` rendering (D7): ONLY for `setup`/`doctor`, and only when the
// flag is given — every other verb, and these two without `--pretty`, stay
// byte-identical to the wrapEnvelope + JSON path. `--pretty` itself IS
// CTR001's documented exception here: an explicit human-readable rendering
// opt-out via an explicit flag, not a verb's default payload.
// Default (non-`--json`) rendering for `fgos plan-lint`: prints each unit
// alongside the catalog's own `description` text, so a reader can see a
// registered capability's real meaning next to a unit whose own title text
// reads nothing like it (e.g. a unit titled "extract shared driver
// discipline" declaring `code:implement` -- the description makes clear
// that is the canonical coding-implementation capability, not a mismatch).
function renderPlanLintReport(data) {
  const lines = [];
  lines.push(`fgos plan-lint: ${data.path}`);
  lines.push(data.ok ? 'OK -- no hard findings' : 'FAILED -- hard findings present');
  lines.push('');
  for (const unit of data.units) {
    const capText = unit.capability ?? '(none)';
    const descText = unit.description ? ` -- ${unit.description}` : '';
    lines.push(`[${unit.source}] ${unit.unit} :: ${capText}${descText}`);
  }
  if (data.findings.length > 0) {
    lines.push('');
    lines.push('Findings:');
    for (const f of data.findings) {
      lines.push(`  ${f.severity.toUpperCase()} ${f.code} (line ${f.line ?? '-'}): ${f.message}`);
    }
  }
  return `${lines.join('\n')}\n`;
}

function renderPretty(verb, data) {
  const lines = [];
  if (verb === 'doctor') {
    lines.push(bold('fgos doctor'));
    if (data.fixed) {
      for (const f of data.fixed) {
        lines.push(formatCheck(true, `fix: ${f.id}`, f.message));
      }
    }
    for (const c of data.checks) {
      lines.push(formatCheck(c.passed, c.description, c.message));
    }
  } else if (verb === 'setup') {
    lines.push(bold('fgos setup'));
    if (data.deprecationMessage) {
      lines.push(formatCheck(true, 'legacy compatibility command', data.deprecationMessage));
    }
    for (const rc of data.rcFilesInserted) {
      lines.push(formatCheck(true, `inserted shell-integration source line`, rc));
    }
    for (const rc of data.rcFilesAlreadyConfigured) {
      lines.push(formatCheck(true, `already sourced`, rc));
    }
    if (data.rcWriteDeclinedReason) {
      lines.push(formatCheck(false, 'skipped shell-profile line', data.rcWriteDeclinedReason));
    }
    lines.push(
      formatCheck(
        true,
        data.configCreated
          ? 'created .fgos/config.json with current defaults'
          : data.configAddedKeys.length > 0
            ? `added missing config keys: ${data.configAddedKeys.join(', ')}`
            : 'config already up to date',
        data.configPath,
      ),
    );
    lines.push(
      formatCheck(
        data.hooksWired,
        data.hooksWired
          ? 'core.hooksPath wired to .githooks'
          : data.hooksSkippedExisting
            ? `core.hooksPath already set to "${data.hooksSkippedExisting}" — left untouched, main-checkout lock is NOT active`
            : 'core.hooksPath not wired (no .git checkout here)',
        'main-checkout lock hook',
      ),
    );
    if (typeof data.skillWrappersGenerated === 'number') {
      lines.push(
        formatCheck(
          true,
          data.skillsSourceCopied
            ? `copied .agents/skills and generated ${data.skillWrappersGenerated} .claude/skills wrapper(s)`
            : `regenerated ${data.skillWrappersGenerated} .claude/skills wrapper(s)`,
          '.agents/skills is the canonical source',
        ),
      );
    }
  }
  return `${lines.join('\n')}\n`;
}

// tsk-56t D2: the read verbs the decision names — not every
// `requiresExistingStore: false` verb (that set also includes `session`/
// `setup`/`doctor`, which never touch `.fgos/` at all, and `init`, which
// gets its own opposite linked-worktree refusal above). `schedule` added
// by tsk-3u2 (post-tsk-3c7 independent review): it reads the exact same
// store state `conflicts` does, but was missing here — from a linked
// worktree with no `.fgos/`, it silently returned `{waves:[],cycles:[]}`

// (indistinguishable from "graph clean") instead of this warning.
//
// `gate-bypass`/`doc-sources`/`lock-status` added by tsk-3g5 (post-tsk-3u2
// independent review, same audit gap this set has already been widened
// twice for): all three are `requiresExistingStore: false` and share the
// identical bug class. `gate-bypass` is the sharpest instance —
// unwarned, it reports a CONFIDENTLY WRONG safety-policy level from a
// worktree (verified: `"off"` from a `.fgos/`-less worktree vs the real
// main checkout's `"standard"`) rather than an honestly-empty result, the
// opposite direction of "looks safer than reality" a caller checking
// bypass posture needs to be warned about. `doc-sources` silently returns
// `count: 0` (indistinguishable from "no captures exist"); `lock-status`
// is structurally forced to report the lock as `free` with no store to
// read a real lock state from.
// `evolve` added by tsk-5iv D3 (round-3 review, MEDIUM): same bug class
// again -- `requiresExistingStore: false`, silently returns `[]` (an
// empty-store `rankCandidates` result) from a `.fgos/`-less worktree
// instead of its real candidate list. This is the fourth time this set
// has been widened for the identical gap (tsk-3u2, tsk-3g5, now this).
//
// `docs-index` was investigated for the same fix (CONTEXT.md D3 originally
// named it too) and found NOT to belong here: verified by reading its own
// handler (the `docs-index` case above) -- its `docPath`/`title` entries
// come from a real `fs.readdirSync` scan of `docs/` under `repoRoot`
// (`path.dirname(dir)`), which is correct and complete regardless of
// whether `.fgos/` exists, and its `sourceCaptureId` bookkeeping already
// has its own dedicated degrade-safe guard (`storeReachable`, tsk-f31,
// just above: preserves a doc's prior `sourceCaptureId` instead of
// regressing it to null when the store is unreachable). Adding this
// verb's generic "this view may be empty" warning would be actively
// MISLEADING here -- its view is never empty or wrong from a worktree --
// so it stays out, correcting CONTEXT.md D3's original premise for this
// one verb with real evidence found during implementation.
//
// `main-checkout-reset` is deliberately NOT added here either: it is
// destructive, not merely read-stale, and tsk-5iv D1 above gives it its
// own hard refusal instead of a soft warning.
const STORE_MISSING_WARNING_VERBS = new Set([
  'list', 'ready', 'graph', 'stale', 'check', 'rollup', 'show', 'conflicts', 'triage', 'schedule',
  'gate-bypass', 'doc-sources', 'lock-status', 'recheck-blocked',
]);

// State/root-resolution investigation (docs/history/agent-coordination-state-root):
// a worktree made OUTSIDE fgOS's own lifecycle (a plain `git worktree add`,
// or an external harness's own worktree tool -- never `fgos pick`/`take`'s
// `createWorktree`, which strips `.fgos/` per ADR0020, nor `fgos session
// start`, which symlinks it) inherits a REAL, git-tracked, but
// frozen-at-branch-point `.fgos/` snapshot. Because `.fgos/` exists there,
// the `requiresExistingStore` ENOENT guard just above never fires, and
// `dataDir()`'s cwd-strict resolution (D5) silently accepts that
// disconnected snapshot as if it were the live store.
//
// This is a hand-verified classification, not `entry.touchesState`
// (COMMAND_REGISTRY) alone -- RFC-review-lite round `coord_state_root_rfc_20260909`
// found that flag too coarse for several verbs. EVERY `touchesState: true`
// verb (44 total) was individually read in this file's own `case` block for
// this pass -- not just the ones a reviewer happened to name -- to sort into
// exactly one of:
//
// 1. `MUTATING_ONLY_VERBS` -- a single id/text argument, no subcommand
//    branching, always mutating when it reaches its handler at all.
// 2. `MUTATING_SUBCOMMAND_PREDICATES` -- genuinely mixed: a real read-only
//    invocation shape exists alongside a real mutating one. Each entry is a
//    `(positional, flags) => boolean` answering "does THIS invocation
//    mutate", read off that verb's own case block, never guessed:
//      - `session`: `start`/`end`/`gc` mutate, `list` reads. `repoRoot`
//        here is raw `process.cwd()` (see the case block), not
//        `resolveMainCheckoutRoot` -- unlike group 4 below, this one
//        genuinely needs the guard.
//      - `goal`: `set` mutates (`setFocus`), `show` reads (`goalFocusShow`).
//      - `gateway`: `start`/`stop` mutate the gateway process/registry,
//        `status` only reads it.
//      - `knowledge`: `attest` mutates, `status` only reads (`rebuild` +
//        filtering, no write call).
//      - `coordination`: `run`/`launch-master-loop` dispatch and can close
//        a session; `show`/`chain` are explicitly commented "never appends
//        an event" in their own case block.
//      - `merge`: `next` mutates (`mergeNext`), `list` only reads
//        (`mergeList`) -- found during this verification, named by neither
//        RFC-review objector.
//      - `evolve`: contrary to the RFC-review round's own objector claim
//        ("bare vs. `--pick`"), the case block's own D15 comment says
//        `--submit <id>` is the ONLY mutating action on the whole
//        evolve/Gate A surface -- bare `evolve` AND `evolve --pick` are
//        both read-only (rank/inspect candidates, no write). Re-verified
//        against the current code rather than trusted secondhand.
//      - `dispatch`: `show-run`/`watch` never write; `recover` writes a
//        Run's own controlEpoch/recovery-commands.jsonl only when --action
//        is given (the bare observe form stays as read-only as show-run).
// 3. Deliberately NOT guarded, already self-correcting via
//    `resolveMainCheckoutRoot(process.cwd())` when `--dir` is omitted (own
//    case-block comments, same mechanism `approve`/`sync-root`/
//    `promote-to-component`/`catchup`/`unclaim` already use, so a second
//    guard here would be redundant, not additive): `setup`, `doctor`,
//    `uninstall`.
// 4. Deliberately NOT guarded, not the shared-truth hazard this guard
//    exists for -- each writes only a local, per-checkout, gitignored
//    artifact by design, never a shared event: `rebuild` (regenerates the
//    local `state.json` cache FROM the local event log -- no new event),
//    `tool` (both `check`, which writes only `.fgos/`'s local status
//    overlay per its own case-block comment, and `query`, pure read).
// 5. Deliberately NOT guarded, not an `.fgos` event-log operation at all --
//    `preflight` resolves its own root independently via `git rev-parse
//    --show-toplevel` against `--dir`-or-cwd, never through `dir`/`state.json`.
// 6. Already excluded, each with its own dedicated, already-tested
//    worktree guard predating this investigation entirely: `init` (own
//    dedicated check just below), `approve`/`sync-root`/
//    `promote-to-component`/`catchup`/`unclaim` (own `repoRoot`, own
//    `isMainWorktree` guard), and `return` -- found the hard way (a live
//    regression during this verification pass, not caught by only
//    sampling the first ~15 lines of its case block the way the other 20
//    verbs in group 1 were confirmed safe): `return`'s own registered-
//    session check (`insideRegisteredSession` via `listSessions` +
//    `isMainWorktree(repoRoot)`, ~line 3862) is deliberately MORE
//    permissive than this guard's own `isSessionWorktree` -- it exempts
//    ANY registered session worktree, spike-proven correct there, with
//    its own distinct refusal message an existing test
//    (`test/cli/fgos-return.test.mjs`) already pins. A second, differently-
//    worded guard ahead of it would only ever preempt it, never add
//    coverage. This file's own `return` case block is ~360 lines, by far
//    the longest of the 21 candidates -- the lesson generalized: a short
//    block sampled at its start is reliable, a long one is not, without
//    reading (or grepping for `isMainWorktree`/`process.cwd()`) the whole
//    thing.
const MUTATING_ONLY_VERBS = new Set([
  'submit', 'take', 'pick', 'move', 'edit', 'ask', 'answer', 'gate-approve', 'reject',
  'add', 'discover', 'plan', 'retrospective', 'cleanup', 'compound', 'resolve-park-reason',
  'handoff', 'handoff-return', 'decision', 'report', 'topic', 'doc', 'repair',
]);

const MUTATING_SUBCOMMAND_PREDICATES = {
  session: (positional) => ['start', 'end', 'gc'].includes(positional[0]),
  goal: (positional) => positional[0] === 'set',
  gateway: (positional) => ['start', 'stop'].includes(positional[0]),
  lock: (positional) => positional[0] === 'fence',
  knowledge: (positional) => positional[0] === 'attest',
  coordination: (positional, flags) => [
    'run', 'close', 'launch-master-loop', 'start', 'operation', 'authorize-and-dispatch',
    'fan-out', 'contribution', 'human-turn', 'disposition', 'specialist-authorize',
  ].includes(positional[0]) || (positional[0] === 'recover' && flags.action !== undefined),
  merge: (positional) => positional[0] === 'next',
  // `dispatch show-run`/`watch` never write; `dispatch recover` writes
  // (controlEpoch bump + one recovery-commands.jsonl line) only when
  // --action is given -- the bare observe form stays read-only.
  dispatch: (positional, flags) => positional[0] === 'recover' && flags.action !== undefined,
};

// True iff THIS invocation (verb + already-parsed positional/flags) will
// reach a handler that mutates `.fgos/` state -- the single predicate the
// disconnected-worktree guard below gates on. Combines groups 1 and 2 above;
// every other verb answers false (never reaches a mutating handler, or is
// independently protected already, per groups 3-6).
function isMutatingInvocation(verb, positional, flags) {
  if (MUTATING_ONLY_VERBS.has(verb)) return true;
  const predicate = MUTATING_SUBCOMMAND_PREDICATES[verb];
  return predicate ? predicate(positional, flags) : false;
}

const ALLOWED_HOOK_KINDS = new Set(['dispatch-decide', 'decision-question']);

async function handleHook(rest) {
  const [kind, ...flags] = rest;
  if (!kind || kind === '--help' || kind === '-h') {
    process.stdout.write(
      'Usage: fgos hook <dispatch-decide|decision-question> [--format=standard|agy]\n\n' +
        'Execute managed hook guards for supported coding agents (Claude, Codex, AGY, OMP, Pi).\n',
    );
    process.exit(0);
  }

  if (!ALLOWED_HOOK_KINDS.has(kind)) {
    process.stderr.write(`Error: Unknown hook kind "${kind}". Allowed kinds: dispatch-decide, decision-question\n`);
    process.exit(1);
  }

  let rawStdin = '';
  try {
    rawStdin = fs.readFileSync(0, 'utf8');
  } catch {
    rawStdin = '';
  }

  let parsed = null;
  if (rawStdin && rawStdin.trim()) {
    try {
      parsed = JSON.parse(rawStdin);
    } catch {
      parsed = null;
    }
  }

  const isAgyFormat =
    flags.includes('--format=agy') || (parsed && typeof parsed === 'object' && parsed.toolCall !== undefined);

  if (isAgyFormat) {
    if (kind === 'dispatch-decide') {
      const toolInput = parsed?.toolCall?.args || {};
      const payloadCwd =
        Array.isArray(parsed?.workspacePaths) && parsed.workspacePaths[0]
          ? parsed.workspacePaths[0]
          : process.cwd();
      const subagentType =
        typeof toolInput.subagent_type === 'string' && toolInput.subagent_type.trim()
          ? toolInput.subagent_type
          : typeof toolInput.agent === 'string' && toolInput.agent.trim()
            ? toolInput.agent
            : 'general-purpose';

      try {
        const { decideExecutorCli } = await import('../src/runner/dispatch.mjs');
        const decided = await decideExecutorCli(undefined, {
          cwd: payloadCwd,
          for: subagentType,
          needsSoul: true,
          hasLiveTaskAccess: true,
        });
        if (decided.mechanism !== 'in-process') {
          process.stdout.write(
            JSON.stringify({
              decision: 'deny',
              reason: `BLOCKED: this subagent call resolves to out-of-process dispatch (no native in-process handler for "${subagentType}"). Run it through ${runDoorHint({ cwd: payloadCwd, executorId: decided.executorId, capability: subagentType })} instead.`,
            }) + '\n',
          );
          process.exit(0);
        }
      } catch {
        // fail-open
      }
      process.stdout.write(JSON.stringify({ decision: 'allow' }) + '\n');
      process.exit(0);
    } else if (kind === 'decision-question') {
      const toolName = parsed?.toolCall?.name || '';
      if (toolName === 'AskUserQuestion' || toolName === 'ask' || toolName === 'ask_question') {
        try {
          const { checkDecisionQuestion, describeDecisionQuestion } = await import(
            '../src/state/decision-question.mjs'
          );
          const questions = Array.isArray(parsed?.toolCall?.args?.questions)
            ? parsed.toolCall.args.questions
            : [];
          const textToCheck = questions
            .flatMap((q) => [
              q?.question,
              Array.isArray(q?.options) && q.options.length > 0
                ? `Options:\n${q.options.map((o) => `- ${o?.label ?? ''}: ${o?.description ?? ''}`).join('\n')}`
                : '',
            ])
            .filter(Boolean)
            .join('\n');
          const missing = checkDecisionQuestion(textToCheck);

          if (missing.length > 0) {
            process.stdout.write(
              JSON.stringify({
                decision: 'deny',
                reason: `BLOCKED: write the analysis before asking. Missing parts of the decision-question template: ${missing.map((p) => p.title).join(', ')}.\n${describeDecisionQuestion()}`,
              }) + '\n',
            );
            process.exit(0);
          }
        } catch {
          // fail-open
        }
      }
      process.stdout.write(JSON.stringify({ decision: 'allow' }) + '\n');
      process.exit(0);
    }
  }

  const scriptPath = path.resolve(
    path.dirname(fileURLToPath(import.meta.url)),
    '..',
    'scripts',
    `${kind}-hook.mjs`,
  );
  if (!fs.existsSync(scriptPath)) {
    process.stderr.write(`Error: Hook script not found at ${scriptPath}\n`);
    process.exit(1);
  }

  const child = spawnSync(process.execPath, [scriptPath, ...flags], {
    input: rawStdin,
    stdio: ['pipe', 'inherit', 'inherit'],
    env: process.env,
  });

  if (child.error) {
    process.stderr.write(`Error invoking hook script: ${child.error.message}\n`);
    process.exit(1);
  }

  process.exit(child.status ?? (child.signal ? 1 : 0));
}

async function main() {
  const [, , verb, ...rest] = process.argv;
  // This process is a controller: Ctrl-C and SIGTERM cancel the attempts it started (the library asks for it, never assumes it).
  enableCancelOnSignal();
  // `hook` keeps the agent's raw argv, but its help is still the manifest door.
  if (verb === 'hook' && (rest.includes('--help') || rest.includes('-h'))) {
    handleVerbHelp(verb, { help: true, ...(rest.includes('--json') ? { json: true } : {}) }, []);
    return;
  }
  if (verb === 'hook') {
    await handleHook(rest);
    return;
  }


  if (verb === '--help' || verb === '-h') {
    handleHelp(rest);
    return;
  }

  // tsk-5z0: which pre-handler fault the code is currently exposed to, so the
  // catch below can tell a malformed CALL apart from a verb's own refusal
  // without reading `err.message` (that would couple this to ~73 hand-written
  // strings and misclassify the moment one is reworded). Each assignment
  // names what the very next statement can throw; `null` means "past the
  // pre-handler region — whatever fails now is the verb answering correctly".
  // `parseArgs` sits inside the try for exactly this reason: outside it, an
  // arg-parse fault never reached this catch at all and could not be recorded.
  let faultClass = 'arg-parse';
  let dir;
  try {
    const { flags, positional } = parseArgs(rest);

    // Same rule as the Rust host: any exact `--help`/`-h` token asks for help,
    // even where the parser took it as the previous flag's value.
    if ((rest.includes('--help') || rest.includes('-h')) && handleVerbHelp(verb, flags, positional)) {
      return;
    }

    faultClass = 'unknown-flag';
    const flagEntry = COMMAND_REGISTRY.find((e) => e.name === verb);
    const unknownFlag = flagEntry && !flagEntry.nativeOnly ? unknownFlagMessage(flagEntry, flags, positional) : null;
    if (unknownFlag) throw new StoreError('validation', unknownFlag);

    faultClass = 'dir-invalid';
    dir = dataDir(flags.dir);
    // tsk-4fu-2: a verb registered `requiresExistingStore: true`
    // (command-registry.mjs) reads/writes through this `dir` — refuse
    // before ever reaching its handler when `.fgos/` isn't there yet,
    // instead of letting `appendEventCore`'s own `mkdirSync` silently
    // create a fresh, empty one (the worktree phantom-store hazard this
    // item closes). `init` is deliberately never in that set — it is the
    // one legitimate door that creates `.fgos/` — but gets the opposite
    // check: refuse when `cwd` is a linked worktree, the one remaining
    // path that could recreate a live `.fgos/` there and defeat ADR0020.
    const entry = COMMAND_REGISTRY.find((e) => e.name === verb);
    if (entry?.nativeOnly) {
      process.stderr.write(`fgos: "${verb}" chỉ có ở Rust host.\n`);
      process.exit(4);
    }
    faultClass = 'store-missing';
    if (entry?.requiresExistingStore && !fs.existsSync(dir)) {
      throw new StoreError(
        'validation',
        `.fgos/ not found at "${dir}" -- run "fgos init" here first, or check you are not inside a linked worktree (worktrees never carry .fgos/, per ADR0020: docs/decisions/0020-chan-fgos-khoi-worktree-worker.md).`,
      );
    }
    // State/root-resolution investigation: a disconnected-snapshot hazard
    // remains distinct from the ENOENT case just above — a worktree made
    // outside fgOS's own lifecycle carries a real, frozen `.fgos/` copy
    // that reads/writes here would silently target instead of the live
    // main store. `fs.existsSync(dir)` is REQUIRED here, not implied by the
    // ENOENT check above: that check only throws for
    // `requiresExistingStore: true` verbs (every `MUTATING_ONLY_VERBS`
    // member is one), but `MUTATING_SUBCOMMAND_PREDICATES` also covers
    // `session`, whose `requiresExistingStore` is `false` BY DESIGN --
    // `fgos session start` from inside a genuinely `.fgos/`-less
    // ADR0020-stripped worktree is the exact legitimate case that verb
    // exists to serve (D10: symlink `.fgos/` INTO a worktree that does not
    // have it yet), and would be wrongly refused here without this check
    // (found live: a real regression in
    // `test/cli/fgos-session.test.mjs` during this pass's own full-suite
    // verification). Skipped entirely when `--dir` was passed explicitly
    // (tsk-56t D1's own escape hatch — the caller took responsibility for
    // that root already, evaluating `isMainWorktree`/`isSessionWorktree`
    // against `process.cwd()` in that case would check the wrong root).
    // `isSessionWorktree` (never just a bare `.fgos` symlink presence check
    // — see its own doc comment) admits the one other legitimate non-main
    // case, an ALREADY-CREATED `fgos session start` worktree.
    faultClass = 'disconnected-worktree-store';
    if (
      flags.dir === undefined &&
      isMutatingInvocation(verb, positional, flags) &&
      fs.existsSync(dir) &&
      !isMainWorktree(process.cwd()) &&
      !isSessionWorktree(process.cwd())
    ) {
      throw new StoreError(
        'validation',
        `"${verb}" refused: "${process.cwd()}" is a linked worktree whose .fgos/ at "${dir}" is a real but disconnected snapshot, never the shared store outside "fgos pick"/"fgos take" (ADR0020-stripped) or "fgos session start" (symlinked) -- pass --dir <mainRoot> to reach the real store explicitly, e.g. ` +
          '`--dir "$(git rev-parse --path-format=absolute --git-common-dir | xargs dirname)"`.',
      );
    }
    faultClass = 'init-in-worktree';
    if (verb === 'init' && !isMainWorktree(process.cwd())) {
      throw new StoreError(
        'validation',
        `"fgos init" refused inside a linked worktree ("${process.cwd()}") -- worktrees never carry .fgos/ by design (ADR0020); run "fgos init" from the main checkout instead.`,
      );
    }
    // tsk-56t D2: these read verbs are `requiresExistingStore: false` by
    // design (a fresh non-worktree dir with no store yet is a legitimate
    // "not evaluated" case, not an error) — but that same tolerance means a
    // worktree-resident session that forgets `--dir` sees a silent, real-
    // looking empty view instead of a signal that the actual store lives
    // elsewhere. `ready`/`triage` can return a bare array when unpaginated
    // (paginateVerbResult), so this can never be a JSON `data` field without
    // changing that shape only in this one runtime case — a stderr line
    // keeps stdout's `data` shape byte-identical in every case, mirroring
    // this file's existing stdout=data/stderr=diagnostics split above.
    if (STORE_MISSING_WARNING_VERBS.has(verb) && !fs.existsSync(dir) && !isMainWorktree(process.cwd())) {
      process.stderr.write(
        `fgos: warning: .fgos/ not found at "${dir}" -- this view may be empty because the real store lives elsewhere (worktrees never carry .fgos/, per ADR0020); pass --dir <mainRoot> to read it.\n`,
      );
    }
    // Past this line the verb's own handler runs, and its refusals ("work X
    // not found", an Iron Law trip, a held lock) are correct answers rather
    // than misuse — so nothing there is recorded. The one exception is an
    // unknown verb: its error is thrown deep inside `runVerb`, where position
    // alone would file it as an ordinary refusal, but the registry lookup
    // above already answers it without new machinery. The error itself still
    // comes from `runVerb` unchanged.
    faultClass = entry ? null : 'unknown-verb';
    const data = await runVerb(verb, flags, positional, dir, rest);
    if (flags.pretty && (verb === 'setup' || verb === 'doctor')) {
      process.stdout.write(renderPretty(verb, data));
    } else if (verb === 'plan-lint' && !flags.json) {
      process.stdout.write(renderPlanLintReport(data));
    } else {
      process.stdout.write(`${JSON.stringify(wrapEnvelope(data), null, 2)}\n`);
    }
    // `run` and foreground `workflow` outcomes map to canonical execution exit codes
    // (0 pass, 4 policy-refusal, 10 provider-limit, 11 execution-failure, 12 partial-writes,
    // 13 blocked, 14 findings, RUL99).
    // `plan-lint` is the verb whose exit code is data-dependent (0 clean, 1 a hard finding present).
    // `doctor --strict` exits 1 when any check still fails after optional fixes ran.
    const isExecutionRun = verb === 'run';
    const isForegroundWorkflow = verb === 'workflow'
      && ['start', 'resume', 'answer'].includes(positional[0])
      && flags.foreground === true
      && data?.status !== 'running'
      && data?.outcome !== undefined
      && data?.outcome !== null;
    const doctorFailed = verb === 'doctor' && flags.strict === true && data.checks.some((c) => !c.passed);

    if (isExecutionRun && data?.outcome) {
      process.exitCode = exitCodeForOutcome(data.outcome);
    } else if (isForegroundWorkflow) {
      process.exitCode = exitCodeForOutcome(data.outcome);
    } else if (verb === 'plan-lint') {
      process.exitCode = data.ok ? 0 : 1;
    } else if (doctorFailed) {
      process.exitCode = 1;
    } else {
      process.exitCode = 0;
    }
  } catch (err) {
    // tsk-5z0: record before reporting, and only say the record exists when
    // one actually landed — `recordInvocationFault` returns null when the
    // fault is a verb's own refusal, when there is no store to write to, or
    // when the write itself failed. It never throws, so the two statements
    // below stay exactly what they were.
    const recorded = recordInvocationFault({
      fgosDir: dir,
      cwd: process.cwd(),
      verb,
      faultClass,
      message: err.message,
      argv: process.argv.slice(2),
    });
    process.stderr.write(`fgos: ${err.message}\n`);
    if (recorded) {
      process.stderr.write(`fgos: invocation fault recorded to ${recorded}\n`);
    }
    if (err instanceof DispatchError || (verb === 'dispatch' && err.errorClass && err.errorClass !== 'validation')) {
      process.exitCode = 1;
    } else {
      process.exitCode = EXIT_CODES[categoryOf(err)] ?? 1;
    }
  }
}

main();

