  return false;
}

if (sub !== undefined) {
  if (!entry.subcommands) {
    refuseHelp(`${verb} takes no sub-verb (got "${sub}"). Usage: fgos ${verb} --help [--json]`);
    return false;
  }

const option = words.find((a) => a.startsWith('-'));
if (option !== undefined) {
  refuseHelp(`unknown option "${option}" for --help. Usage: fgos --help [<verb> [<sub>]] [--json]`);
